/** Neutral, portable frontend starters. No source data or services are imported. */
const FAMILIES = ['campaign-page','event-page','application-form','referral-flow','member-portal','relationship-workspace','assistant','directory','handbook','crew-planner','gallery','invoice'];
const escape = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow = '<span aria-hidden="true">↗</span>';

export function skeletonFamily(item = {}) {
  if (FAMILIES.includes(item.skeletonKey)) return item.skeletonKey;
  if (item.category === 'Forms') return 'application-form';
  if (item.category === 'Portals') return 'member-portal';
  if (item.preview === 'referral') return 'referral-flow';
  if (item.preview === 'event') return 'event-page';
  if (item.preview === 'directory') return 'directory';
  if (item.preview === 'gallery') return 'gallery';
  return 'campaign-page';
}

/** Local demo arithmetic: quantities and USD rates support two decimal places. */
export function calculateInvoice(lines = []) {
  if (!Array.isArray(lines) || lines.length > 100) throw new RangeError('Use at most 100 line items.');
  function hundredths(value, maximum) {
    if (!['number','string'].includes(typeof value)) throw new RangeError('Enter a valid amount.');
    const text = String(value).trim();
    if (!/^(?:\d{1,9}(?:\.\d{1,2})?|\.\d{1,2})$/.test(text)) throw new RangeError('Use non-negative amounts with at most two decimal places.');
    const [whole = '', fraction = ''] = text.split('.');
    const scaled = Number(whole || 0) * 100 + Number(fraction.padEnd(2, '0'));
    if (scaled > maximum * 100) throw new RangeError('Amount exceeds this demo’s limit.');
    return scaled;
  }
  const lineTotalsCents = lines.map(line => {
    const quantity = hundredths(line?.quantity, 10000);
    const rate = hundredths(line?.unitPrice, 1000000);
    return Math.floor((quantity * rate + 50) / 100); // Round each line half-up to cents.
  });
  return { lineTotalsCents, totalCents: lineTotalsCents.reduce((sum, value) => sum + value, 0) };
}

