function nav(links = [['Overview','#overview'],['Get started','#start']]) {
  return `<div class="sk-wrap"><header class="sk-nav"><a class="sk-brand" href="#top">Your project.</a><nav>${links.map(([label,url])=>`<a href="${escape(url)}">${escape(label)}</a>`).join('')}</nav></header></div>`;
}
const art = (className='') => `<div class="sk-art ${className}" role="img" aria-label="Neutral visual placeholder"><span></span><i>Your visual goes here</i></div>`;
const footer = () => '<footer class="sk-footer"><span>Your project.</span><p>Frontend starter · Demo interactions only · Nothing is sent or saved to a service.</p></footer>';
const button = (text,extra='') => `<button class="sk-button" type="button" ${extra}>${escape(text)} ${arrow}</button>`;
const section = (id,title,text,body) => `<section class="sk-section" id="${id}"><div class="sk-section-head"><h2>${title}</h2><p>${text}</p></div>${body}</section>`;

function campaign(item) {
  const invitation = item.id === 'fomo-invite';
  const titles = ['Find your people.','Make something happen.','Bring everyone together.'];
  const cards = `<div class="sk-grid">${titles.map((title,i)=>`<article class="sk-card"><span class="sk-index">0${i+1} · YOUR PATH</span><h3>${title}</h3><p>A short description of who this path is for, what it offers, and what happens next.</p><a href="#path-${i+1}">Explore this path ${arrow}</a></article>`).join('')}</div>`;
  if (invitation) return `${nav()}<main class="sk-wrap"><section class="sk-section" id="overview"><p class="sk-kicker">A place to begin</p><h1>Three ways in.</h1><p class="sk-lead">Choose the opportunity that feels like you.</p>${cards}</section>${titles.map((t,i)=>section(`path-${i+1}`,t,'Replace this introduction with the details of your own program.',`<div class="sk-callout"><h3>Your next step</h3><p>Explain the commitment, the opportunity, and how someone gets involved.</p><div class="sk-actions" style="margin-top:20px">${button('Try this path','data-demo-action="This path is ready to connect to your application flow."')}</div></div>`)).join('')}<div id="start"></div>${footer()}</main>`;
  return `${nav()}<main class="sk-wrap"><section class="sk-hero"><div><p class="sk-kicker">Your community · Your program</p><h1>A little more<br>possibility.</h1><p class="sk-lead">One clear idea. A few ways to join in. Give your audience a place to start.</p><a class="sk-button" href="#overview">Find your path ${arrow}</a></div>${art()}</section>${section('overview','Where do you want to start?','Three clear routes into your program. Make each next step easy to understand.',cards)}${titles.map((title,i)=>`<section class="sk-section sk-split" id="path-${i+1}">${i%2===0?art():''}<div><p class="sk-kicker">0${i+1} · Program section</p><h2>${title}</h2><p class="sk-lead">Use this section to explain the experience, who it serves, and why it is worth their time.</p><ul class="sk-list"><li><b>01</b>Describe the opportunity.</li><li><b>02</b>Set a clear expectation.</li><li><b>03</b>Offer one useful next step.</li></ul></div>${i%2?art():''}</section>`).join('')}${section('start','Pick up where you left off.','A home for returning members and people ready to take the next step.',`<div class="sk-actions">${button('Explore the demo','data-demo-action="Demo complete. Replace this action with your own approved destination."')}<a class="sk-button sk-secondary" href="#overview">See the paths</a></div>`)}${footer()}</main>`;
}

function eventPage(item) {
  const dinner = item.id === 'fomo-dinners';
  const scoreboard = item.id === 'fomo-gameday';
  const hero = dinner?'A reason to<br>get together.':scoreboard?'Two teams.<br>One occasion.':'A shared goal.<br>A little rivalry.';
  const overview = dinner?'The experience':scoreboard?'The scoreboard':'The opportunity';
  const top = scoreboard?`<div class="sk-score"><div><small>EXAMPLE TEAM A</small><b>—</b></div><span>vs.</span><div><small>EXAMPLE TEAM B</small><b>—</b></div></div>`:art(dinner?'sk-poster':'');
  return `${nav([['The experience','#overview'],['How it works','#steps'],['Join in','#start']])}<main class="sk-wrap"><section class="sk-hero"><div><p class="sk-kicker">Your event · Coming together</p><h1>${hero}</h1><p class="sk-lead">Tell people what you are bringing together, what they can expect, and how to take part.</p><div class="sk-actions"><a class="sk-button" href="#start">Get involved ${arrow}</a><a class="sk-button sk-secondary" href="#overview">The details</a></div></div>${top}</section>${section('overview',overview,'Replace these sample details with your own format, timing, and eligibility.',`<div class="sk-grid">${['The format','The people','The commitment'].map((t,i)=>`<article class="sk-card"><span class="sk-index">0${i+1}</span><h3>${t}</h3><p>Describe this part of the experience with a clear, concrete explanation.</p><span class="sk-pill">Details to come</span></article>`).join('')}</div>`)}${section('steps','A simple way to take part.','Keep the journey short and expectations clear.',`<div class="sk-step-list"><div><b>1</b>Tell us a little about your group.</div><div><b>2</b>Review the plan and participation details.</div><div><b>3</b>Bring your people together.</div></div>`)}${section('board',scoreboard?'The activity feed.':'A place for every group.','Sample presentation only. Connect verified data before publishing.',`<div class="sk-table-wrap"><table class="sk-table"><thead><tr><th>Group</th><th>Location</th><th>Status</th></tr></thead><tbody>${[1,2,3].map(n=>`<tr><td>Example group 0${n}</td><td>Your location</td><td><span class="sk-pill">Sample entry</span></td></tr>`).join('')}</tbody></table></div>`)}${section('start',dinner?'Host your own gathering.':'Bring your group in.','This button shows a local demo confirmation. No registration is submitted.',`<div class="sk-callout"><h3>Your next occasion starts here.</h3><p>Add your real application or signup connection when this starter becomes your project.</p><div class="sk-actions" style="margin-top:22px">${button(dinner?'Try host interest':'Try registration','data-demo-action="Interest noted for this demo only. No application was sent."')}</div></div>`)}${footer()}</main>`;
}

function formConfig(item) {
  const contact=[{label:'Your name',name:'name',placeholder:'Example person'},{label:'Email address',name:'email',type:'email',placeholder:'you@example.test'}];
  if (/hq-visit/.test(item.id||'')) return {title:'Make time<br>to connect.',intro:'A short visit request with a preferred date, time, and a little context.',steps:[['Pick a date and time',[{label:'Preferred date',name:'date',type:'date'},{label:'Preferred time',name:'time',type:'time'}]],['Your details',[...contact,{label:'What would you like to discuss?',name:'purpose',kind:'textarea'}]]],submit:'Preview request'};
  if (item.id==='fomo-campus-visit') return {title:'A new place.<br>A familiar face.',intro:'A guided trip request, from the travel plan to the people and purpose.',steps:[['Plan your trip',[{label:'Starting point',name:'from',placeholder:'Your location'},{label:'Destination',name:'destination',placeholder:'Your destination'},{label:'Preferred date',name:'date',type:'date'}]],['Your plan',[{label:'How will you get there?',name:'travel',options:['Choose a travel option','Ground travel','Air travel','Other']},{label:'What will you do?',name:'plan',kind:'textarea'}]],['Your details',contact]],submit:'Preview trip request'};
  if (item.id==='fomo-clan-claim') return {title:'Make a home<br>for your group.',intro:'Group details first. Then a local sample link to share with the people joining you.',steps:[['Your group',[{label:'Group name',name:'group',placeholder:'Your group'},{label:'Location or institution',name:'location',placeholder:'Your location'},{label:'Expected members',name:'members',type:'number',min:1},...contact]],['Your account',[{label:'Account username',name:'username',placeholder:'your-name'},{label:'A note for your group',name:'note',kind:'textarea',optional:true}]]],submit:'Create demo group',claim:true};
  if (item.id==='fomo-dinner-application') return {title:'Bring good<br>people together.',intro:'One question at a time. A simple application to propose a gathering.',steps:[['First, your name',[contact[0]]],['Your email',[contact[1]]],['Where would you host?',[{label:'City or location',name:'city',placeholder:'Your city'}]],['Who would you invite?',[{label:'Describe your group',name:'guests',kind:'textarea'}]],['Why this gathering?',[{label:'Your idea',name:'idea',kind:'textarea'}]]],submit:'Preview application'};
  if (item.id==='bijan-build-request') return {title:'Start with<br>your idea.',intro:'A focused project inquiry that captures the goal, scope, and best next conversation.',steps:[['What are you making?',[{label:'Project name',name:'project',placeholder:'Your next project'},{label:'What should it do?',name:'scope',kind:'textarea'}]],['A little context',[{label:'Project type',name:'type',options:['Choose a type','Website','Internal tool','Something else']},{label:'Your timing',name:'timing',placeholder:'Your preferred timeframe'}]],['How can we reach you?',contact]],submit:'Preview project inquiry'};
  return {title:'Your next<br>chapter.',intro:'A clear registration journey, one simple question at a time.',steps:[['Your name',[contact[0]]],['Your email',[contact[1]]],['Where are you based?',[{label:'Location or institution',name:'location',placeholder:'Your location'}]],['Your group',[{label:'Group name',name:'group',placeholder:'Your group'}]],['Your role',[{label:'Role in the group',name:'role',options:['Choose a role','Organizer','Member','Other']}]],['How many people?',[{label:'Expected group size',name:'members',type:'number',min:1}]]],submit:'Preview registration'};
}
function field(f) {
  const attrs=`name="${escape(f.name)}" ${f.optional?'':'required'} autocomplete="off"`;
  const control=f.kind==='textarea'?`<textarea ${attrs} rows="3" maxlength="1000" placeholder="Your answer"></textarea>`:f.options?`<select ${attrs}>${f.options.map((o,i)=>`<option value="${i?escape(o):''}">${escape(o)}</option>`).join('')}</select>`:`<input ${attrs} type="${f.type||'text'}" ${f.min?`min="${f.min}"`:''} maxlength="200" placeholder="${escape(f.placeholder||'Your answer')}">`;
  return `<label>${escape(f.label)}${f.optional?' <small>Optional</small>':''}${control}</label>`;
}
function application(item) {
  const config=formConfig(item);
  return `${nav([['Application','#start']])}<main class="sk-wrap"><div class="sk-form-layout" id="start"><div class="sk-form-intro"><p class="sk-kicker">Your project · Application</p><h1>${config.title}</h1><p>${config.intro}</p><div class="sk-step-list"><div><b>1</b>A few useful details</div><div><b>2</b>A clear next step</div></div><p class="sk-note">Use sample details. This frontend demo never sends a request or reserves a place.</p></div><div class="sk-form-panel"><div data-wizard-shell><div class="sk-step-heading"><span data-step-count>STEP 1 OF ${config.steps.length}</span><span>Local demo</span></div><div class="sk-progress" aria-hidden="true"><span data-step-progress></span></div><form method="dialog" data-step-form novalidate data-claim="${!!config.claim}">${config.steps.map(([title,fields],i)=>`<fieldset data-step="${i}" ${i?'hidden':''}><legend tabindex="-1">${escape(title)}</legend><div class="sk-fields">${fields.map(field).join('')}</div></fieldset>`).join('')}<div class="sk-form-actions"><button class="sk-button sk-secondary" type="button" data-step-back hidden>Back</button><button class="sk-button" type="button" data-step-next>Continue ${arrow}</button><button class="sk-button" type="submit" data-step-submit hidden>${config.submit} ${arrow}</button></div></form></div><div class="sk-success" data-form-success hidden><span class="sk-success-mark" aria-hidden="true">✓</span><h2>That’s the full flow.</h2><p>This is a demo confirmation. No details were sent, saved to a service, or booked.</p>${config.claim?'<div class="sk-copybox"><input value="/join/demo-group" readonly aria-label="Sample group link"><button class="sk-button" type="button" data-copy>Copy</button></div>':''}<button class="sk-button sk-secondary" type="button" data-form-reset>Start again</button></div></div></div>${footer()}</main>`;
}

function referral() {
  return `${nav()}<main class="sk-center" id="overview"><p class="sk-kicker">Your project · Invite someone</p><h1>A good thing.<br>Worth sharing.</h1><p class="sk-lead">A simple personal link, a clear invitation, and an easy way to share it.</p><div class="sk-form-panel" id="start"><h2>Build your sample link</h2><form method="dialog" data-referral-form><div class="sk-fields"><label>Your username<input name="username" required maxlength="40" placeholder="your-name" pattern="[A-Za-z0-9_-]+" title="Use letters, numbers, underscores, or dashes." autocomplete="off"></label><button class="sk-button" type="submit">Build link ${arrow}</button></div></form><div data-referral-result hidden><p class="sk-note">A local example path, ready to connect to your own referral system.</p><div class="sk-copybox"><input data-referral-link readonly aria-label="Generated sample link"><button class="sk-button" type="button" data-copy>Copy</button></div></div><p class="sk-note" style="margin:19px 0 0">No account is created and no referral is tracked.</p></div><div class="sk-step-list"><div><b>1</b>Create your personal link.</div><div><b>2</b>Share it with someone who belongs here.</div><div><b>3</b>Explain what happens when they join.</div></div></main>`;
}
function portal() {
  return `${nav([['Your group','#overview'],['Join','#start']])}<main class="sk-wrap"><header class="sk-portal-hero" id="overview"><span class="sk-pill">Example group · Your location</span><h1>Your people.<br>One place.</h1><p class="sk-lead">A member portal with a clear group identity, shared progress, and a guided way to join.</p></header><div class="sk-portal-grid"><section class="sk-card"><p class="sk-kicker">Sample progress</p><div class="sk-big-number"><span data-member-count>0</span><span style="font-size:18px;color:#aaa"> / 10</span></div><div class="sk-progress-labels"><span>Demo members</span><span>Sample goal</span></div><div class="sk-progress"><span data-member-progress></span></div><p>Use this space for a real, verified milestone once your membership system is connected.</p><div class="sk-copybox"><input value="/join/your-group" readonly aria-label="Sample group link"><button class="sk-button" type="button" data-copy>Copy link</button></div></section><section class="sk-card" id="start"><p class="sk-kicker">Join the group</p><h2 style="font-size:29px">Make yourself at home.</h2><p>Try the member signup. This only updates the sample progress on this page.</p><form method="dialog" data-member-form><div class="sk-fields"><label>Your username<input name="member" required maxlength="40" placeholder="example-member" autocomplete="off"></label><button class="sk-button" type="submit">Join the demo ${arrow}</button></div></form><p class="sk-note" data-member-status role="status"></p></section></div>${section('steps','A few simple steps.','A practical place for download links, account setup, or instructions.',`<div class="sk-grid">${['Create your account','Join the right group','See what comes next'].map((t,i)=>`<article class="sk-card"><span class="sk-index">0${i+1}</span><h3>${t}</h3><p>Replace this instruction with the verified step your members need.</p></article>`).join('')}</div>`)}${footer()}</main>`;
}

function workspace(item) {
  const visits=item.id==='milo-visit-console';
  const links=item.id==='fomo-claim-links';
  const label=visits?'Visit requests':links?'Group links':'Relationships';
  return `<div class="sk-workspace"><aside class="sk-side"><a class="sk-brand" href="#top">Your workspace.</a><p class="sk-kicker">Your tools</p><nav><button type="button" aria-pressed="true" data-work-filter="all">${label}</button><button type="button" aria-pressed="false" data-work-filter="review">Needs review</button><button type="button" aria-pressed="false" data-work-filter="ready">Ready</button></nav><p class="sk-note" style="margin-top:30px">Frontend starter.<br>All records are fictional.</p></aside><main class="sk-work-main"><header class="sk-work-header"><div><p class="sk-kicker">A clear view of the next step</p><h1>${label}.</h1></div>${button('Try an action','data-demo-action="This is a local workspace demo. Connect your access control and verified records before using it with a team."')}</header><div class="sk-stats"><div class="sk-stat">3<small>Example records</small></div><div class="sk-stat">2<small>Need review</small></div><div class="sk-stat">1<small>Ready for next step</small></div></div><div class="sk-work-columns"><section><label class="sk-search">Find a record<input data-record-search type="search" placeholder="Search example records" autocomplete="off"></label><div class="sk-table-wrap"><table class="sk-table"><thead><tr><th>${links?'Group':'Person'}</th><th>Status</th><th>Details</th></tr></thead><tbody>${[1,2,3].map(n=>`<tr data-record-row data-status="${n===3?'ready':'review'}"><td>Example ${links?'group':'person'} 0${n}</td><td><span class="sk-pill">${n===3?'Ready':'Needs review'}</span></td><td><button class="sk-button sk-secondary" type="button" data-record="${n}">Open</button></td></tr>`).join('')}</tbody></table></div></section><aside class="sk-detail-panel"><p class="sk-kicker">Selected record</p><h2 data-record-title>Example ${links?'group':'person'} 01</h2><p>A neutral detail panel for context, a reviewed next step, and a short local note.</p>${links?'<div class="sk-copybox"><input value="/join/example-group" readonly aria-label="Sample group link"><button class="sk-button" type="button" data-copy>Copy</button></div>':''}<form method="dialog" data-note-form><label>Add a sample note<textarea name="note" rows="3" required maxlength="300" placeholder="Your next step"></textarea></label><button class="sk-button sk-secondary" type="submit">Add local note</button></form><ul data-notes></ul><p class="sk-note">Notes disappear when this page is reloaded. No message is sent.</p></aside></div></main></div>`;
}
function directory() {
  const groups=['Explore the program','Join the team','Bring people together','Member resources','Applications','Useful tools'];
  return `${nav()}<main class="sk-wrap"><section class="sk-section" id="overview"><p class="sk-kicker">Your project · The directory</p><h1>Every path.<br>One starting point.</h1><p class="sk-lead">Organize the journeys, pages, and resources that make up your project.</p><label class="sk-search">Find your next step<input data-directory-search type="search" placeholder="Search the directory" autocomplete="off"></label><div class="sk-grid" data-directory>${groups.map((t,i)=>`<article class="sk-card sk-directory-card" data-directory-item><span class="sk-index">0${i+1} · RESOURCE</span><h3>${t}</h3><p>A brief explanation of who this resource is for and what they can do here.</p><button class="sk-text-button" type="button" data-directory-open>View resource ${arrow}</button><div class="sk-directory-detail" hidden>This is a sample destination. Replace it with the page or workflow that belongs to your project.</div></article>`).join('')}</div><p class="sk-note" data-directory-empty hidden>No matching resources. Try a different phrase.</p></section><section class="sk-section" id="start"><h2>Everything has a place.</h2><p class="sk-lead">Give each audience a clear route, and keep your destinations up to date.</p></section>${footer()}</main>`;
}
function handbook() {
  const chapters=['The opportunity','Your responsibilities','A useful first week','Working together','Practical guidelines'];
  return `${nav([['The handbook','#overview']])}<main class="sk-wrap"><div class="sk-handbook"><nav class="sk-toc" aria-label="Handbook chapters"><p class="sk-kicker">In this guide</p>${chapters.map((t,i)=>`<a href="#chapter-${i+1}">0${i+1} · ${t}</a>`).join('')}</nav><article class="sk-prose" id="overview"><p class="sk-kicker">Your project · Field guide</p><h1>Your first<br>chapter.</h1><p class="sk-lead">A practical guide to the work, the expectations, and the support around you.</p>${chapters.map((t,i)=>`<section id="chapter-${i+1}"><p class="sk-kicker">0${i+1}</p><h2>${t}.</h2><p>Replace this with the context your team needs. Explain the purpose, give a concrete example, and make the next step clear.</p><div class="sk-callout"><h3>One thing to remember</h3><p>A short, useful principle that helps someone make a good decision.</p></div><details><summary>What should I do first?</summary><p>Describe the first practical action, who can help, and how to know it is complete.</p></details><details><summary>Where can I get help?</summary><p>Add the appropriate support route when you connect this guide to your workspace.</p></details></section>`).join('')}</article></div>${footer()}</main>`;
}
function crew() {
  const columns=[['The host',['Confirm the plan','Welcome your people','Wrap up the gathering']],['The setup',['Prepare the space','Check the essentials','Reset the space']],['The story',['Capture the moment','Collect the materials','Prepare the recap']]];
  return `${nav([['The plan','#overview'],['Working sheet','#start']])}<main class="sk-wrap"><header class="sk-planner" id="overview"><p class="sk-kicker">Your project · Working together</p><h1>A small crew.<br>A clear plan.</h1><p class="sk-lead">A shared run of show with responsibilities, checklists, and a place for the next task.</p><div class="sk-pills"><span class="sk-pill">Your event</span><span class="sk-pill">Your date</span><span class="sk-pill">Your location</span></div></header><section id="start"><div class="sk-section-head"><h2>The working sheet.</h2><p><span data-task-count>0 of 9</span> demo tasks complete</p></div><div class="sk-progress"><span data-task-progress></span></div><div class="sk-tasks">${columns.map(([title,tasks],i)=>`<section class="sk-task-column"><span class="sk-index">0${i+1} · RESPONSIBILITY</span><h3>${title}</h3><div data-task-list>${tasks.map(t=>`<label class="sk-check"><input type="checkbox" data-task><span>${t}</span></label>`).join('')}</div></section>`).join('')}</div><form method="dialog" class="sk-add-task" data-task-form><input name="task" required maxlength="100" placeholder="Add a sample task to the host’s list" aria-label="New sample task"><button class="sk-button" type="submit">Add task ${arrow}</button></form><p class="sk-note" style="margin-top:16px">Changes stay on this page until you reload. Team sync is not connected.</p></section><div style="height:45px"></div>${footer()}</main>`;
}
function assistant() {
  return `<main class="sk-assistant-stage"><button class="sk-launcher" type="button" data-chat-open aria-label="Open demo assistant" aria-expanded="false"><span class="sk-assistant-mark" aria-hidden="true"></span></button><section class="sk-chat" role="dialog" aria-label="Demo project assistant" data-chat hidden><header class="sk-chat-header"><strong>Your assistant</strong><button type="button" data-chat-close aria-label="Close assistant">×</button></header><div class="sk-chat-note">Frontend demo · AI is not connected</div><div class="sk-chat-body" data-chat-body><h2>A little help<br>for your people.</h2><p>A reusable conversation panel with suggested questions, message history, and a clear next step.</p><div class="sk-chat-prompts"><button type="button" data-chat-prompt>What can this assistant do?</button><button type="button" data-chat-prompt>How would I get started?</button></div><div data-chat-messages role="log" aria-live="polite"></div></div><form method="dialog" class="sk-chat-form" data-chat-form><input name="question" maxlength="500" required placeholder="Try a sample question…" aria-label="Question for the demo assistant" autocomplete="off"><button class="sk-button" type="submit" aria-label="Send demo question">↑</button></form></section></main>`;
}

function gallery() {
  const groups=['Spaces','Objects','Studies'];
  return `${nav([['Selected work','#work'],['About','#about']])}<main class="sk-wrap"><section class="sk-section" id="work"><p class="sk-kicker">Your studio · Selected work</p><h1>A point of view.</h1><p class="sk-lead">A quiet home for photographs, projects, and the way you see things.</p><div class="sk-gallery-filters" role="group" aria-label="Filter gallery">${['All',...groups].map((label,i)=>`<button type="button" class="sk-button sk-secondary" data-gallery-filter="${label}" aria-pressed="${i===0}">${label}</button>`).join('')}</div><p class="sk-note" data-gallery-count role="status">6 sample pieces</p><div class="sk-gallery-grid">${Array.from({length:6},(_,i)=>`<figure class="sk-gallery-item" data-gallery-item data-gallery-category="${groups[i%3]}"><div class="sk-gallery-visual" role="img" aria-label="Neutral visual placeholder ${i+1}"></div><figcaption><strong>Example piece 0${i+1}</strong><span>${groups[i%3]}</span></figcaption></figure>`).join('')}</div></section>${section('about','The work behind the work.','Replace these placeholders with your own images, captions, and story. No original photographs are included.',`<div class="sk-callout"><h3>Your studio, in a few words.</h3><p>Explain what you make, how you approach it, and the projects you want to explore next.</p></div>`)}${footer()}</main>`;
}
function invoiceRow(name='New item',quantity='1',rate='0') { return `<tr data-invoice-row><td><input data-invoice-description value="${escape(name)}" maxlength="120" aria-label="Item description"></td><td><input data-invoice-quantity type="number" value="${quantity}" min="0" max="10000" step="0.01" required aria-label="Quantity"></td><td><input data-invoice-rate type="number" value="${rate}" min="0" max="1000000" step="0.01" required aria-label="Unit price in USD"></td><td><output data-invoice-line aria-label="Line total">—</output></td><td><button type="button" class="sk-text-button" data-invoice-remove aria-label="Remove line item">Remove</button></td></tr>`; }
function invoice() {
  return `${nav([['Line items','#items'],['Demo details','#details']])}<main class="sk-wrap"><section class="sk-section" id="items"><p class="sk-kicker">Your studio · Local calculator</p><h1>A simple invoice.</h1><p class="sk-lead">Build a sample total from quantities and rates. Nothing is stored, sent, or paid.</p><div class="sk-field-row" style="margin-bottom:26px"><label>Sample client<input placeholder="Example client" maxlength="120" autocomplete="off"></label><label>Sample project<input placeholder="Example project" maxlength="120" autocomplete="off"></label></div><div class="sk-table-wrap"><table class="sk-table sk-invoice-table"><thead><tr><th scope="col">Item</th><th scope="col">Quantity</th><th scope="col">Rate (USD)</th><th scope="col">Total</th><th scope="col">Edit</th></tr></thead><tbody data-invoice-lines>${invoiceRow('Planning','1','125')}${invoiceRow('Design','2','75')}${invoiceRow('Review','0.5','60')}</tbody></table></div><div class="sk-invoice-summary"><button class="sk-button sk-secondary" type="button" data-invoice-add>Add line item ${arrow}</button><strong>Sample total <output data-invoice-total aria-label="Sample invoice total">—</output></strong></div><p class="sk-note" data-invoice-status role="status"></p></section>${section('details','A calculation, ready to adapt.','Frontend demo only. Reloading clears your changes.',`<p class="sk-invoice-note">Quantities and rates accept up to two decimal places. Each line rounds to the nearest cent before adding the total. This sample does not add taxes, discounts, payment links, or invoice delivery.</p>`)}${footer()}</main>`;
}


/** Accept only text and bounded theme values; client input never becomes markup. */
export function draftTheme(custom = {}) {
  const project=custom.project||{}, draft=custom.draft||{}, brand=project.brand||{}, copy=draft.copy||{};
  const color=(value,fallback)=>/^#[a-f0-9]{6}$/i.test(value||'')?value:fallback;
  const text=(value,max)=>typeof value==='string'?value.slice(0,max):'';
  const logo=typeof brand.logo==='string'&&brand.logo.length<700000&&/^data:image\/(?:png|jpeg|webp);base64,[a-z0-9+/=]+$/i.test(brand.logo)?brand.logo:'';
  return {name:text(project.name,120),title:text(copy.title,240),description:text(copy.description,4000),eyebrow:text(copy.eyebrow,120),cta:text(copy.cta,120),logo,
    accent:color(brand.accent,'#343430'),bg:color(brand.bg,'#f7f7f2'),ink:color(brand.ink,'#444435'),font:({system:'-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif',editorial:'Georgia,"Times New Roman",serif',modern:'Arial,Helvetica,sans-serif'})[brand.font]||'-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif'};
}
function draftCSS(custom) {
  if(!custom)return '';
  const t=draftTheme(custom);
  return '.sk{--bg:'+t.bg+';--ink:'+t.ink+';--surface:color-mix(in srgb,'+t.bg+' 94%, '+t.ink+');--line:color-mix(in srgb,'+t.ink+' 18%, '+t.bg+');background:'+t.bg+';color:'+t.ink+';font-family:'+t.font+'}.sk p,.sk label,.sk small{color:color-mix(in srgb,'+t.ink+' 72%, '+t.bg+')}.sk .sk-kicker{color:color-mix(in srgb,'+t.ink+' 65%, '+t.bg+')!important}.sk .sk-button:not(.sk-secondary),.sk .sk-launcher{background:'+t.accent+';border-color:'+t.accent+';color:'+contrastInk(t.accent)+'!important}.sk .sk-progress>span{background:'+t.accent+'}.sk .sk-brand img{max-height:34px;max-width:130px;object-fit:contain}.sk :is(h1,h2,h3){overflow-wrap:anywhere}.sk .sk-lead{white-space:pre-line}';
}
function contrastInk(hex) {
  const rgb=hex.slice(1).match(/../g).map(c=>{const n=parseInt(c,16)/255;return n<=.04045?n/12.92:((n+.055)/1.055)**2.4;});
  return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]>.179?'#161616':'#ffffff';
}
function draftSurfaces(custom) {
  if(!custom)return '';
  return '.sk :is(.sk-form-panel,.sk-stats>div,.sk-table-wrap,.sk-task-column,.sk-detail-panel,.sk-chat,.sk-score,.sk-step-list>div,input,select,textarea){background:var(--surface);color:var(--ink);border-color:var(--line)}.sk :is(.sk-side,.sk-art,.sk-callout,.sk-copybox,.sk-pill,.sk-chat-note,.sk-gallery-visual){background:color-mix(in srgb,var(--bg) 90%,var(--ink));color:var(--ink);border-color:var(--line)}.sk :is(.sk-table td,.sk-table th,.sk-stat,.sk-big-number,.sk-form-panel legend,.sk-list li){color:var(--ink)}.sk .sk-button.sk-secondary{color:var(--ink)!important;border-color:var(--line)}';
}
function customizeMarkup(html,custom) {
  if(!custom)return html;
  const t=draftTheme(custom);
  if(t.name){html=html.replace(/(<a class="sk-brand"[^>]*>)[\s\S]*?(<\/a>)/g,(_,a,b)=>a+(t.logo?'<img src="'+escape(t.logo)+'" alt="'+escape(t.name)+'">':escape(t.name))+b).replace('<span>Your project.</span>','<span>'+escape(t.name)+'</span>');}
  if(t.title)html=html.replace(/(<h1\b[^>]*>)[\s\S]*?(<\/h1>)/,(_,a,b)=>a+escape(t.title)+b);
  if(t.title&&!html.includes('<h1'))html=html.replace(/(<h2\b[^>]*>)[\s\S]*?(<\/h2>)/,(_,a,b)=>a+escape(t.title)+b);
  if(t.eyebrow)html=html.replace(/(<p class="sk-kicker"[^>]*>)[\s\S]*?(<\/p>)/,(_,a,b)=>a+escape(t.eyebrow)+b);
  if(t.description){
    if(/<p class="sk-lead"/.test(html))html=html.replace(/(<p class="sk-lead"[^>]*>)[\s\S]*?(<\/p>)/,(_,a,b)=>a+escape(t.description)+b);
    else if(/<\/h1>\s*<p>/.test(html))html=html.replace(/(<\/h1>\s*<p>)[\s\S]*?(<\/p>)/,(_,a,b)=>a+escape(t.description)+b);
    else if(html.includes('<h1'))html=html.replace('</h1>','</h1><p class="sk-lead">'+escape(t.description)+'</p>');
    else html=html.replace(/(<\/h2>\s*<p>)[\s\S]*?(<\/p>)/,(_,a,b)=>a+escape(t.description)+b);
  }
  if(t.cta)html=html.replace(/(<(?:a|button) class="sk-button"[^>]*>)[\s\S]*?(<\/(?:a|button)>)/,(_,a,b)=>a+escape(t.cta)+' '+arrow+b);
  return html;
}

function markup(item,custom) {
  const family=skeletonFamily(item);
  const renderers={'campaign-page':campaign,'event-page':eventPage,'application-form':application,'referral-flow':referral,'member-portal':portal,'relationship-workspace':workspace,assistant,directory,handbook,'crew-planner':crew,gallery,invoice};
  const labels=Array.isArray(item.skeletonSections)?item.skeletonSections.filter(s=>typeof s==='string').slice(0,10):[];
  return `<div class="sk" id="top" data-skeleton-family="${family}">${customizeMarkup(renderers[family](item),custom)}${family!=='assistant'&&labels.length?`<div class="sk-wrap"><details class="sk-structure"><summary>Layout notes</summary><ol>${labels.map(s=>`<li>${escape(s.slice(0,160))}</li>`).join('')}</ol></details></div>`:''}<div class="sk-toast" data-toast role="status" hidden></div></div>`;
}

/** Shared initializer; kept self-contained so the download can inline it. */
function attachInteractions(root) {
  const q = (selector) => root.querySelector(selector);
  const all = (selector) => [...root.querySelectorAll(selector)];
  const controller = new AbortController();
  const options = { signal: controller.signal };
  let toastTimer;
  let lastChatFocus;
  let step = 0;
  let memberCount = 0;
  const members = new Set();
  const notes = new Map();
  let currentRecord = '1';
  let workFilter = 'all';
  const toast = (text) => { const node=q('[data-toast]');node.textContent=text;node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{node.hidden=true;},3500); };
  const listen = (node,event,handler) => node?.addEventListener(event,handler,options);
  const fields = all('[data-step]');
  function updateStep(focus=false) {
    if (!fields.length) return;
    fields.forEach((field,i)=>{field.hidden=i!==step;});
    q('[data-step-count]').textContent=`STEP ${step+1} OF ${fields.length}`;
    q('[data-step-progress]').style.width=`${(step+1)/fields.length*100}%`;
    q('[data-step-back]').hidden=step===0;
    q('[data-step-next]').hidden=step===fields.length-1;
    q('[data-step-submit]').hidden=step!==fields.length-1;
    if(focus) fields[step].querySelector('legend')?.focus();
  }
  function validStep() { return [...fields[step].querySelectorAll('input,select,textarea')].every(input=>input.reportValidity()); }
  listen(q('[data-step-next]'),'click',()=>{if(validStep()){step+=1;updateStep(true);}});
  listen(q('[data-step-back]'),'click',()=>{step=Math.max(0,step-1);updateStep(true);});
  listen(q('[data-step-form]'),'submit',event=>{event.preventDefault();if(!validStep())return;if(step<fields.length-1){step+=1;updateStep(true);return;}q('[data-wizard-shell]').hidden=true;q('[data-form-success]').hidden=false;q('[data-form-reset]').focus();});
  listen(q('[data-form-reset]'),'click',()=>{q('[data-step-form]').reset();step=0;q('[data-form-success]').hidden=true;q('[data-wizard-shell]').hidden=false;updateStep(true);});
  updateStep();
  listen(q('[data-referral-form]'),'submit',event=>{event.preventDefault();if(!event.currentTarget.reportValidity())return;const input=event.currentTarget.elements.username;q('[data-referral-link]').value=`/join?ref=${encodeURIComponent(input.value.trim())}`;q('[data-referral-result]').hidden=false;});
  listen(q('[data-member-form]'),'submit',event=>{event.preventDefault();if(!event.currentTarget.reportValidity())return;const name=event.currentTarget.elements.member.value.trim().toLowerCase();if(members.has(name)){q('[data-member-status]').textContent='That example member is already in this demo.';return;}members.add(name);memberCount+=1;q('[data-member-count]').textContent=String(memberCount);q('[data-member-progress]').style.width=`${Math.min(memberCount*10,100)}%`;q('[data-member-status]').textContent='Added to this page’s demo only. No real membership was created.';event.currentTarget.reset();});
  listen(q('[data-directory-search]'),'input',event=>{const query=event.target.value.trim().toLowerCase();const cards=all('[data-directory-item]');cards.forEach(card=>{card.hidden=!card.textContent.toLowerCase().includes(query);});q('[data-directory-empty]').hidden=cards.some(card=>!card.hidden);});
  function filterRecords() {const query=q('[data-record-search]')?.value.trim().toLowerCase()||'';all('[data-record-row]').forEach(row=>{row.hidden=!(row.textContent.toLowerCase().includes(query)&&(workFilter==='all'||row.dataset.status===workFilter));});}
  listen(q('[data-record-search]'),'input',filterRecords);
  function paintNotes() {const list=q('[data-notes]');list.replaceChildren();for(const text of notes.get(currentRecord)||[]){const li=document.createElement('li');li.textContent=text;list.append(li);}}
  listen(q('[data-note-form]'),'submit',event=>{event.preventDefault();const input=event.currentTarget.elements.note;if(!input.reportValidity())return;const list=notes.get(currentRecord)||[];list.push(input.value.trim());notes.set(currentRecord,list);paintNotes();event.currentTarget.reset();});
  function taskProgress() {const checks=all('[data-task]');const complete=checks.filter(c=>c.checked).length;if(q('[data-task-count]'))q('[data-task-count]').textContent=`${complete} of ${checks.length}`;if(q('[data-task-progress]'))q('[data-task-progress]').style.width=`${complete/checks.length*100}%`;}
  listen(root,'change',event=>{if(event.target.matches('[data-task]'))taskProgress();});
  listen(q('[data-task-form]'),'submit',event=>{event.preventDefault();const input=event.currentTarget.elements.task;if(!input.reportValidity())return;const label=document.createElement('label');label.className='sk-check';const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.setAttribute('data-task','');const span=document.createElement('span');span.textContent=input.value.trim();label.append(checkbox,span);q('[data-task-list]').append(label);event.currentTarget.reset();taskProgress();});
  taskProgress();
  function paintInvoice(){if(!q('[data-invoice-total]'))return;const rows=all('[data-invoice-row]');try{const totals=calculateInvoice(rows.map(row=>({quantity:row.querySelector('[data-invoice-quantity]').value,unitPrice:row.querySelector('[data-invoice-rate]').value})));const money=cents=>`$${(cents/100).toFixed(2)}`;rows.forEach((row,i)=>{row.querySelector('[data-invoice-line]').textContent=money(totals.lineTotalsCents[i]);});q('[data-invoice-total]').textContent=money(totals.totalCents);q('[data-invoice-status]').textContent='USD · Local demo only. Nothing is sent or saved.';}catch{rows.forEach(row=>{row.querySelector('[data-invoice-line]').textContent='—';});q('[data-invoice-total]').textContent='—';q('[data-invoice-status]').textContent='Enter non-negative quantities and rates with up to two decimal places (quantity ≤ 10,000; rate ≤ 1,000,000).';}}
  listen(root,'input',event=>{if(event.target.matches('[data-invoice-quantity],[data-invoice-rate]'))paintInvoice();});
  paintInvoice();
  function openChat(){lastChatFocus=document.activeElement;q('[data-chat]').hidden=false;q('[data-chat-open]').hidden=true;q('[data-chat-open]').setAttribute('aria-expanded','true');q('[data-chat-form] input').focus();}
  function closeChat(){q('[data-chat]').hidden=true;q('[data-chat-open]').hidden=false;q('[data-chat-open]').setAttribute('aria-expanded','false');(lastChatFocus?.isConnected?lastChatFocus:q('[data-chat-open]')).focus();}
  function chat(message){const messages=q('[data-chat-messages]');for(const [role,text] of [['user',message],['assistant','Demo response: this panel is ready for your approved knowledge and secure AI service. This starter does not call a model or send your question anywhere.']]){const p=document.createElement('p');p.className=`sk-chat-message ${role}`;p.textContent=text;messages.append(p);}q('[data-chat-body]').scrollTop=q('[data-chat-body]').scrollHeight;}
  listen(q('[data-chat-form]'),'submit',event=>{event.preventDefault();const input=event.currentTarget.elements.question;const text=input.value.trim();if(!text)return;chat(text.slice(0,500));input.value='';input.focus();});
  listen(root,'keydown',event=>{if(event.key==='Escape'&&q('[data-chat]')&&!q('[data-chat]').hidden){closeChat();event.preventDefault();}});
  listen(root,'click',async event=>{
    const action=event.target.closest('button');if(!action||!root.contains(action))return;
    if(action.hasAttribute('data-demo-action'))toast(action.dataset.demoAction);
    if(action.hasAttribute('data-copy')){const input=action.parentElement.querySelector('input');input.select();try{if(!navigator.clipboard?.writeText)throw Error();await navigator.clipboard.writeText(input.value);toast('Sample link copied.');}catch{toast('Sample link selected. Use your browser’s copy command.');}}
    if(action.hasAttribute('data-directory-open')){const panel=action.nextElementSibling;panel.hidden=!panel.hidden;action.textContent=panel.hidden?'View resource ↗':'Close resource';}
    if(action.hasAttribute('data-work-filter')){workFilter=action.dataset.workFilter;all('[data-work-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===action)));filterRecords();}
    if(action.hasAttribute('data-record')){currentRecord=action.dataset.record;q('[data-record-title]').textContent=action.closest('tr').querySelector('td').textContent;paintNotes();q('[data-note-form]').reset();}
    if(action.hasAttribute('data-chat-open'))openChat();
    if(action.hasAttribute('data-chat-close'))closeChat();
    if(action.hasAttribute('data-chat-prompt'))chat(action.textContent);
    if(action.hasAttribute('data-gallery-filter')){const filter=action.dataset.galleryFilter;all('[data-gallery-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===action)));const pieces=all('[data-gallery-item]');pieces.forEach(piece=>{piece.hidden=filter!=='All'&&piece.dataset.galleryCategory!==filter;});q('[data-gallery-count]').textContent=`${pieces.filter(piece=>!piece.hidden).length} sample pieces`;}
    if(action.hasAttribute('data-invoice-add')){if(all('[data-invoice-row]').length>=20){toast('This demo holds up to 20 line items.');return;}const row=document.createElement('tr');row.setAttribute('data-invoice-row','');row.innerHTML='<td><input data-invoice-description value="New item" maxlength="120" aria-label="Item description"></td><td><input data-invoice-quantity type="number" value="1" min="0" max="10000" step="0.01" required aria-label="Quantity"></td><td><input data-invoice-rate type="number" value="0" min="0" max="1000000" step="0.01" required aria-label="Unit price in USD"></td><td><output data-invoice-line aria-label="Line total">—</output></td><td><button type="button" class="sk-text-button" data-invoice-remove aria-label="Remove line item">Remove</button></td>';q('[data-invoice-lines]').append(row);paintInvoice();row.querySelector('input').focus();}
    if(action.hasAttribute('data-invoice-remove')){action.closest('[data-invoice-row]').remove();paintInvoice();q('[data-invoice-add]').focus();}
  });
  return ()=>{controller.abort();clearTimeout(toastTimer);};
}

export function mountSkeleton(container, item = {}, custom) {
  const style=document.createElement('style');
  style.textContent=STYLES+draftCSS(custom)+draftSurfaces(custom);
  const content=document.createElement('div');
  content.innerHTML=markup(item,custom);
  container.replaceChildren(style,content);
  return attachInteractions(content.querySelector('.sk'));
}

export function buildSkeletonDocument(item = {}, custom) {
  const family=skeletonFamily(item);
  return `<!doctype html>\n<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; connect-src 'none'; form-action 'none'; base-uri 'none'"><title>${escape(custom?.project?.name||'Your project')} — ${escape(family.replaceAll('-',' '))} starter</title><style>html,body{margin:0;padding:0} ${STYLES}${draftCSS(custom)}${draftSurfaces(custom)}</style></head><body>\n<!-- Edit the neutral copy, structure, and styles below. All example interactions are local. -->\n${markup(item,custom)}\n<script>const calculateInvoice=${calculateInvoice.toString()};\n(${attachInteractions.toString()})(document.querySelector('.sk'));<\/script>\n</body></html>`;
}

export function downloadSkeleton(item = {}, custom) {
  const file=new Blob([buildSkeletonDocument(item,custom)],{type:'text/html;charset=utf-8'});
  const url=URL.createObjectURL(file);
  const anchor=document.createElement('a');
  anchor.href=url;
  anchor.download=`${String(custom?.draft?.name||item.id||'your-project').replace(/[^a-z0-9_-]/gi,'-').slice(0,80)}-skeleton.html`;
  document.body.append(anchor);anchor.click();anchor.remove();
  setTimeout(()=>URL.revokeObjectURL(url),1000);
}
